function specSourceText(t, key, values = {}) {
	const supplied = t(key, values);
	if (supplied !== key) return supplied;
	return (specSourceStrings[(navigator.language || "zh-TW").toLowerCase().startsWith("zh") ? "zh-TW" : "en"][key] || key).replace(/\{(\w+)\}/g, (_, name) => String(values[name] ?? ""));
}
